/* Standalone PS2 sample: boots, loads the embedded .uib, replays it,
 * and cycles focus through every node so an emulator screenshot run
 * covers each state. This is the ELF the hardware bring-up checklist
 * (docs/bringup.md) and the CI emulator job drive.
 *
 * Build with the PS2SDK toolchain (see Makefile); the blob is embedded
 * at build time via bin2c, so the ELF is self-contained — no host or
 * memory-card I/O involved in bring-up.
 */

#include <kernel.h>
#include <stdio.h>
#include <gsKit.h>
#include <dmaKit.h>

#include "../ps2ui.h"

/* Generated by bin2c from the baked example blob. */
extern unsigned char ui_uib[];
extern unsigned int size_ui_uib;

/* Frames to hold each focus state — long enough for a screenshot. */
#define FRAMES_PER_STATE 150

/* Build with -DPS2UI_SAMPLE_TELEMETRY for a once-a-second log line on
 * stdout. printf from the EE reaches PCSX2's console log, ps2link, and
 * any TTY hook — no IRX modules, no storage, nothing to mount, which
 * is why this is the first sink rather than USB or UDP: it works on
 * the very first boot, before anything else is proven.
 *
 * The line is machine-fixed and grep-friendly:
 *
 *   ps2ui-telemetry frame=300 fps=60.0 miss=0 ee_us(min/avg/max)=412/430/501
 *       prims=375 hidden=0 slotg=42 slothid=0 sciov=0
 *
 * fps is measured from elapsed wall-clock cycles, not derived from the
 * miss count: a UI running steadily at half rate overruns a field on
 * every frame, so `60 - missed` would report 0 fps for a program
 * rendering perfectly well at 30. They are independent signals and the
 * interval is a real second either way.
 *
 * ee_us is ps2ui_render alone (composition cost, not GPU), measured
 * with the EE's COP0 cycle counter. miss counts frames where the whole
 * loop overran one 60 Hz field.
 *
 * The ps2ui counters are aggregated across the interval, not sampled
 * from its last frame. sciov especially: a nonzero value means a blob
 * deeper than PS2UI_MAX_SCISSOR_DEPTH reached the console, and B16's
 * lesson was that this condition is silent and remote from its cause —
 * sampling it at a 1-in-60 duty cycle would keep it silent 98% of the
 * time. prims/slotg report the interval's peak, which is the number
 * that matters for budgeting.
 */
#ifdef PS2UI_SAMPLE_TELEMETRY
/* COP0 Count on the R5900 ticks once per CPU cycle at 294.912 MHz.
 * TODO(bench): confirm on hardware. Several MIPS implementations tick
 * Count at half the core clock, and if the R5900 is one of them every
 * ee_us here is 2x off. The bench session settles it: render a known
 * fixed workload and compare ee_us against a stopwatch over 600
 * frames. Until then treat ee_us as relative, not absolute. */
#define EE_HZ 294912000u
static inline u32 cop0_count(void)
{
    u32 v;
    /* __asm__ __volatile__, not `asm volatile`: the sample builds
     * -std=c99, which is strict ISO C where `asm` is not a keyword —
     * GCC only spells it that way in the gnu* dialects. The
     * underscored form is available in every mode. */
    __asm__ __volatile__("mfc0 %0, $9" : "=r"(v));
    return v;
}
#endif

/* Build with -DPS2UI_SAMPLE_STATIC to hold the baked initial focus
 * forever instead of walking the graph.
 *
 * Cycling is what you want when a person is watching, and exactly what
 * you cannot have when a machine is diffing: an automated capture lands
 * at whatever wall-clock moment the screenshot fires, so the frame it
 * grabs is not the frame `--preview` rendered, and the comparison is
 * non-deterministic by construction. The CI emulator job builds with
 * this defined; docs/bringup.md drives the cycling build by hand. */
#ifdef PS2UI_SAMPLE_STATIC
#define PS2UI_SAMPLE_CYCLE 0
#else
#define PS2UI_SAMPLE_CYCLE 1
#endif

#ifdef PS2UI_SAMPLE_PROBE
/* Bring-up step 2 as a program, for when solid fills do not appear.
 *
 * The first emulator capture came back 92.8% pure black with every text
 * colour present and correct to within one unit. So the textured path
 * works — atlas, CLUT, CSM1 swizzle, modulate domain — and nothing
 * untextured drew, including `gsKit_clear`, which is not ps2ui's code.
 *
 * What this actually separates is GIF packet encoding, then blending,
 * then the alpha value, which is a sharper instrument than "the clear
 * versus sprites" suggests:
 *
 *   - `gsKit_clear` does not go through `gsKit_prim_sprite`. It builds
 *     a PACKED A+D list via `gsKit_prim_list_sprite_flat`, while
 *     `gsKit_prim_sprite` emits a sprite GIF tag with SPRITE_REGS.
 *     Those are two different packet encodings, and an emulator can
 *     implement one and not the other.
 *   - then ABE off versus on,
 *   - then the alpha value itself, across the ladder below.
 *
 * The ground colour is deliberately not any example's: #1a0e0a is the
 * memcard canvas #0a0e1a with its channels reversed, so a fingerprint
 * cannot be confused with a UI capture in the same log.
 *
 * NOTE: current gsKit does *not* save and restore PrimAlphaEnable
 * around `gsKit_clear` (older versions did). The explicit disable below
 * is load-bearing, not redundant — do not tidy it away. It also means
 * the shipping render loop, which clears with ABE on at alpha 0x80,
 * differs from this probe in exactly the variable under test; if step 2
 * reads clean and the UI still does not, flip that first.
 *
 * A `.uib` is still linked into this ELF (bin2c runs regardless), so a
 * baked blob must exist to build it. Nothing draws it. */
static const unsigned char probe_alphas[] = { 0x20, 0x40, 0x60, 0x7f, 0x80 };

static void probe_frame(GSGLOBAL *gs)
{
    int i;

    gs->PrimAlphaEnable = GS_SETTING_OFF;
    gsKit_clear(gs, GS_SETREG_RGBAQ(0x1a, 0x0e, 0x0a, 0x80, 0x00));

    /* Control: unblended, and a colour used nowhere else. */
    gsKit_prim_sprite(gs, 40.0f, 40.0f, 240.0f, 200.0f, 0,
                      GS_SETREG_RGBAQ(0xff, 0x00, 0x00, 0x80, 0x00));

    /* Same colour every time, only the alpha varies, so a missing rung
     * cannot be blamed on the colour register. Over the #1a0e0a ground
     * the blend equation predicts each rung exactly:
     *
     *   0x20 -> #530a47   0x40 -> #8c0784   0x60 -> #c503c1
     *   0x7f -> #fd00fd   0x80 -> #ff00ff
     *
     * A fingerprint missing only the last one puts the fault precisely
     * at As = 128, which is the value the .uib calls opaque. */
    gs->PrimAlphaEnable = GS_SETTING_ON;
    for (i = 0; i < 5; i++) {
        float x = 20.0f + 120.0f * (float)i;
        gsKit_prim_sprite(gs, x, 248.0f, x + 120.0f, 408.0f, 0,
                          GS_SETREG_RGBAQ(0xff, 0x00, 0xff,
                                          probe_alphas[i], 0x00));
    }
}
#endif

int main(void)
{
    GSGLOBAL *gs;
    ps2ui_ctx ui;
    int rc;
    unsigned frame = 0;

    dmaKit_init(D_CTRL_RELE_OFF, D_CTRL_MFD_OFF, D_CTRL_STS_UNSPEC,
                D_CTRL_STD_OFF, D_CTRL_RCYC_8, 1 << DMA_CHANNEL_GIF);
    dmaKit_chan_init(DMA_CHANNEL_GIF);

    gs = gsKit_init_global();
    gs->PSM = GS_PSM_CT32;
    gs->PSMZ = GS_PSMZ_16S;
    gs->DoubleBuffering = GS_SETTING_ON;
    gs->ZBuffering = GS_SETTING_OFF; /* strict back-to-front paint order */
    gsKit_init_screen(gs);
    gsKit_mode_switch(gs, GS_ONESHOT);

    /* ps2ui blobs carry GS-domain alpha; the standard blend equation
     * (Cs - Cd) * As >> 7 + Cd is exactly what the baker assumed. */
    gs->PrimAlphaEnable = GS_SETTING_ON;

#ifdef PS2UI_SAMPLE_PROBE
    /* No blob, no ps2ui: just the four primitive cases. */
    while (1) {
        probe_frame(gs);
        gsKit_queue_exec(gs);
        gsKit_sync_flip(gs);
    }
#endif

    rc = ps2ui_load(&ui, ui_uib, size_ui_uib);
    if (rc != PS2UI_OK) {
        /* Bring-up step 1 failure: solid red = load error. */
        while (1) {
            gsKit_clear(gs, GS_SETREG_RGBAQ(0x80, 0x00, 0x00, 0x80, 0x00));
            gsKit_queue_exec(gs);
            gsKit_sync_flip(gs);
        }
    }
    if (ps2ui_upload(&ui, gs) != 0) {
        /* Solid yellow = VRAM alloc failure (bring-up step 9). */
        while (1) {
            gsKit_clear(gs, GS_SETREG_RGBAQ(0x80, 0x80, 0x00, 0x80, 0x00));
            gsKit_queue_exec(gs);
            gsKit_sync_flip(gs);
        }
    }

#ifdef PS2UI_SAMPLE_TELEMETRY
    u32 t_min = 0xFFFFFFFFu, t_max = 0, t_sum = 0;
    u32 sec_frames = 0, missed = 0, t_frame_prev = cop0_count();
    u32 elapsed = 0;
    /* Interval aggregates, not a last-frame sample. */
    u32 a_prims = 0, a_hidden = 0, a_slotg = 0, a_slothid = 0, a_sciov = 0;
#endif

    while (1) {
        /* Canvas background: #0a0e1a in flat-shaded full-range RGB. */
        gsKit_clear(gs, GS_SETREG_RGBAQ(0x0a, 0x0e, 0x1a, 0x80, 0x00));
#ifdef PS2UI_SAMPLE_TELEMETRY
        {
            u32 t0 = cop0_count(), dt;
            ps2ui_render(&ui, gs);
            dt = cop0_count() - t0;
            if (dt < t_min) t_min = dt;
            if (dt > t_max) t_max = dt;
            t_sum += dt;
        }
#else
        ps2ui_render(&ui, gs);
#endif
        gsKit_queue_exec(gs);
        gsKit_sync_flip(gs);
#ifdef PS2UI_SAMPLE_TELEMETRY
        {
            /* Wall time of the whole loop, vsync included: more than
             * one field's worth of cycles means the flip missed. */
            u32 now = cop0_count(), loop = now - t_frame_prev;
            if (loop > EE_HZ / 60u + EE_HZ / 600u)
                missed++;
            elapsed += loop;
            t_frame_prev = now;
            sec_frames++;

            /* Peaks for the budgeting numbers, a sum for the alarm:
             * one overflowed frame in the interval must be visible. */
            if (ui.stats.prims > a_prims) a_prims = ui.stats.prims;
            if (ui.stats.skipped_hidden > a_hidden) a_hidden = ui.stats.skipped_hidden;
            if (ui.stats.slot_glyphs > a_slotg) a_slotg = ui.stats.slot_glyphs;
            if (ui.stats.slots_hidden > a_slothid) a_slothid = ui.stats.slots_hidden;
            a_sciov += ui.stats.scissor_overflow;

            /* Report on elapsed time, so the line is a real second at
             * any frame rate rather than 60 frames however long those
             * took. */
            if (elapsed >= EE_HZ) {
                u32 fps10 = (u32)(((u64)sec_frames * 10u * EE_HZ + elapsed / 2u)
                                  / elapsed);
                printf("ps2ui-telemetry frame=%u fps=%u.%u miss=%u "
                       "ee_us(min/avg/max)=%u/%u/%u "
                       "prims=%u hidden=%u slotg=%u slothid=%u sciov=%u\n",
                       frame, fps10 / 10u, fps10 % 10u, missed,
                       t_min / (EE_HZ / 1000000u),
                       (t_sum / sec_frames) / (EE_HZ / 1000000u),
                       t_max / (EE_HZ / 1000000u),
                       a_prims, a_hidden, a_slotg, a_slothid, a_sciov);
                t_min = 0xFFFFFFFFu; t_max = 0; t_sum = 0;
                sec_frames = 0; missed = 0; elapsed = 0;
                a_prims = 0; a_hidden = 0; a_slotg = 0;
                a_slothid = 0; a_sciov = 0;
            }
        }
#endif

        /* Walk every focus state so a timed screenshot sweep sees each
         * one: hold, then move right (wrapping via down) through the
         * graph; when movement dead-ends, jump back to the initial. */
        frame++;
        if (PS2UI_SAMPLE_CYCLE && frame % FRAMES_PER_STATE == 0) {
            if (!ps2ui_move(&ui, PS2UI_RIGHT) && !ps2ui_move(&ui, PS2UI_DOWN))
                ui.focus = ui.hdr->initial_focus;
        }
    }
    return 0;
}
